cd /home/nedlern/nedschorus-logs/transcripts && grep -rl --include=*.jsonl "only survive as long as the worktree" . 2>/dev/null | while read f; do python3 - "$f" <<'EOF'
import json,sys
for line in open(sys.argv[1]):
    try: d=json.loads(line)
    except: continue
    if d.get('type')!='user': continue
    c=d.get('message',{}).get('content')
    texts=[c] if isinstance(c,str) else [b.get('text','') for b in (c or []) if isinstance(b,dict) and b.get('type')=='text']
    for t in texts:
        if 'only survive as long as the worktree' in t and not t.lstrip().startswith(('Another Claude','<','This session','[')) and len(t)<1500:
            print(sys.argv[1], d.get('timestamp'), d.get('userType'), repr(t[:400]))
EOF
done 2>/dev/null | head

cd ~/agents/merge-lane-2 && grep -l -F "obsidian publish" /home/nedlern/nedschorus-logs/transcripts/mac/projects/*/*.jsonl 2>/dev/null; python3 - <<'EOF'
import json,glob
for f in glob.glob('/home/nedlern/nedschorus-logs/transcripts/mac/projects/*/*.jsonl'):
    for line in open(f,errors='replace'):
        if 'bsidian publish' not in line: continue
        try: r=json.loads(line)
        except: continue
        if r.get('type')=='queue-operation':
            print('QUEUE',r.get('timestamp'),f.split('/')[-2],repr(r.get('content'))[:300])
        elif r.get('type')=='user' and not r.get('isMeta'):
            c=r.get('message',{}).get('content')
            if isinstance(c,str) and 'bsidian publish' in c and len(c)<1000: print('USER',r.get('timestamp'),r.get('userType'),f.split('/')[-2],repr(c)[:300])
            elif isinstance(c,list):
                for b in c:
                    if isinstance(b,dict) and b.get('type')=='text' and 'bsidian publish' in b.get('text','') and len(b['text'])<1000: print('USERLIST',r.get('timestamp'),f.split('/')[-2],repr(b['text'])[:300])
EOF

